import com.squareup.moshi.JsonClass
import com.squareup.moshi.Moshi
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertTrue

// LetterJsonAdapter is generated by testKsp, Signature is internal to the module
@JsonClass(generateAdapter = true)
internal data class Letter(val greeting: Greeting, val signature: Signature)

class LetterTest {
    private val adapter = Moshi.Builder().build().adapter(Letter::class.java)

    @Test
    fun `letters survive a round trip`() {
        val letter = Letter(Greeting("Moshi", 2), Signature("build-script"))
        assertEquals(letter, adapter.fromJson(adapter.toJson(letter)))
    }

    @Test
    fun `the adapter is generated`() {
        assertTrue(adapter.toString().startsWith("GeneratedJsonAdapter(Letter)"), adapter.toString())
    }
}
